 const escape=helpers.escapeHTML;let page='<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>灵感一现 · 离线阅读</title><style>body{max-width:960px;margin:40px auto;padding:20px;background:#f5f6ef;color:#344c3b;font:16px/1.8 system-ui}summary{cursor:pointer;font-weight:600}details{padding:18px;margin:12px 0;background:white;border-radius:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere}small{color:#687967}</style><h1>灵感一现 · 离线阅读</h1><p>导出时间 '+escape(now)+'。本页面无需登录或联网；这是阅读快照，修改不自动同步云端。</p>';
 for(const [i,r] of records.entries()){const content=r.original||r.summary||r.next_action||'',md='# '+r.title+'\n\n'+content+'\n\n来源与字段：\n\n```json\n'+JSON.stringify(r,null,2)+'\n```\n';files['wiki/'+String(i+1).padStart(5,'0')+'.md']=md;page+='<details><summary>'+escape(r.title)+'</summary><pre>'+escape(md)+'</pre></details>';}
 page+='<h2>经验学习和沉淀</h2>';for(const article of learn?.articles||[]){page+='<details><summary>'+escape(article.title)+'</summary><pre>'+escape(JSON.stringify(article,null,2))+'</pre></details>';}
 page+='<h2>来源账本</h2>';for(const source of legacy?.sources||[]){page+='<details><summary>'+escape(source.title)+'</summary><pre>'+escape(source.content||'')+'</pre></details>';}
 for(const batch of tables.capture_batches){const obj=await env.BUCKET.get(batch.raw_key);if(!obj)throw captureError('备份中缺少已提交批次，请稍后重试。',503);const packet=await obj.json();files['raw/'+batch.id+'/manifest.json']=JSON.stringify(packet.manifest,null,2);for(const [path,file] of Object.entries(packet.files))files['raw/'+batch.id+'/'+path]=fileBytes(file);}
